public void clearClipRect(){
  if (context.clipRectEnabled) {
    try {
      GL gl=GLContext.getCurrentGL();
      gl.glDisable(GL.GL_SCISSOR_TEST);
      context.clipRectEnabled=false;
      clipX=0;
      clipY=0;
      clipW=0;
      clipH=0;
    } catch (IllegalStateException e) {
      // 处理或记录没有有效OpenGL上下文的情况
    }
  }
}
